package dev.zomboid.clans;
import java.util.*;import net.minecraft.server.*;
public class WaveLootChecks {
 static int checks;static void ok(boolean value,String message){checks++;if(!value)throw new AssertionError(message);}
 public static class Drops {Object mob,source;boolean canceled;List<Object> items=new ArrayList<>(List.of("item"));Drops(Object mob,Object source){this.mob=mob;this.source=source;}public Object getEntity(){return mob;}public Object getSource(){return source;}public List<Object> getDrops(){return items;}public void setCanceled(boolean value){canceled=value;}}
 public static class Experience {Object mob;int xp=20;Experience(Object mob){this.mob=mob;}public Object getEntity(){return mob;}public void setDroppedExperience(int amount){xp=amount;}}
 public static void main(String[]args){MinecraftServer server=new MinecraftServer();PveChecks.World world=new PveChecks.World(server);PveChecks.Mob mob=new PveChecks.Mob(world);mob.tag.putString("FactionPveWave",UUID.randomUUID().toString());PveChecks.Source nature=new PveChecks.Source(null);WaveLoot.death(new PveChecks.Death(mob,nature));Drops drops=new Drops(mob,nature);WaveLoot.drops(drops);ok(drops.canceled&&drops.items.isEmpty(),"natural death prevents corpse handler and loose drops");Experience xp=new Experience(mob);WaveLoot.experience(xp);ok(xp.xp==0,"natural death cannot farm recent-player XP");PveChecks.Player player=new PveChecks.Player(server,world);PveChecks.Source playerDamage=new PveChecks.Source(player);WaveLoot.death(new PveChecks.Death(mob,playerDamage));drops=new Drops(mob,playerDamage);WaveLoot.drops(drops);ok(!drops.canceled&&drops.items.size()==1,"real player finishing damage keeps corpse loot");xp=new Experience(mob);WaveLoot.experience(xp);ok(xp.xp==20,"real player kill keeps native XP");ok(WaveLoot.player(playerDamage),"projectile owner attribution accepts player source");PveChecks.Source npc=new PveChecks.Source(new PveChecks.Mob(world));WaveLoot.death(new PveChecks.Death(mob,npc));drops=new Drops(mob,npc);WaveLoot.drops(drops);ok(drops.canceled,"NPC final hit does not qualify");mob.tag.putBoolean("FactionPveCleanupDeath",true);WaveLoot.death(new PveChecks.Death(mob,playerDamage));drops=new Drops(mob,playerDamage);WaveLoot.drops(drops);ok(drops.canceled,"automatic cleanup marker remains suppressed even if source rewritten");PveChecks.Mob ordinary=new PveChecks.Mob(world);drops=new Drops(ordinary,nature);WaveLoot.drops(drops);ok(!drops.canceled&&drops.items.size()==1,"non wave zombie death unchanged");xp=new Experience(ordinary);WaveLoot.experience(xp);ok(xp.xp==20,"non wave XP unchanged");mob.tag.putBoolean("FactionPveCleanupDeath",false);WaveLoot.death(new PveChecks.Death(mob,nature));drops=new Drops(mob,playerDamage);WaveLoot.drops(drops);ok(drops.canceled,"natural finishing cause stays blocked if delayed drop source credits older player damage");ok(!WaveLoot.player(new PveChecks.Source(new net.neoforged.neoforge.common.util.FakePlayer(server))),"automated fake player cannot qualify as player finishing kill");System.out.println("PASS "+checks+" wave loot attribution checks (API doubles)");}
}
